<template>
  <div class="fade-up">
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:20px">
      <button class="ibtn ibtn-o ibtn-sm" @click="$router.back()">
        <svg viewBox="0 0 24 24"><line x1="19" y1="12" x2="5" y2="12"/><polyline points="12 19 5 12 12 5"/></svg>
      </button>
      <div class="ph" style="margin:0">
        <h1>{{ referral.referral_code }}</h1>
        <p>Referral Details</p>
      </div>
    </div>

    <div v-if="loading" style="text-align:center;padding:44px">
      <div style="width:24px;height:24px;border:2px solid var(--mint);border-top-color:var(--moss);border-radius:50%;animation:spin .7s linear infinite;margin:0 auto"></div>
    </div>

    <template v-else>
      <div class="icard" style="margin-bottom:20px">
        <div class="icard-body" style="display:flex;flex-direction:column;gap:14px">
          <div>
            <div style="font-size:10px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;color:var(--fog);margin-bottom:3px">Status</div>
            <span class="ibadge" :class="'ibadge-' + referral.status">{{ toTitleCase(referral.status) }}</span>
          </div>
          <div>
            <div style="font-size:10px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;color:var(--fog);margin-bottom:3px">Service Type</div>
            <div style="font-size:13px;color:var(--ink)">{{ toTitleCase(referral.referral_type) }}</div>
          </div>
          <div>
            <div style="font-size:10px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;color:var(--fog);margin-bottom:3px">Date Submitted</div>
            <div style="font-size:13px;color:var(--ink)">{{ formatDate(referral.created_at) }}</div>
          </div>
          <div v-if="referral.referrer_name">
            <div style="font-size:10px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;color:var(--fog);margin-bottom:3px">Referred By</div>
            <div style="font-size:13px;color:var(--ink)">{{ referral.referrer_name }}<span v-if="referral.referrer_role"> ({{ toTitleCase(referral.referrer_role) }})</span></div>
          </div>
          <div v-if="referral.nature_of_concern">
            <div style="font-size:10px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;color:var(--fog);margin-bottom:3px">Concern</div>
            <div style="font-size:13px;color:var(--ink);line-height:1.6;background:var(--snow);padding:10px 12px;border-radius:var(--r-sm)">{{ referral.nature_of_concern }}</div>
          </div>
          <div v-if="referral.acknowledged_at">
            <div style="font-size:10px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;color:var(--fog);margin-bottom:3px">Acknowledged</div>
            <div style="font-size:13px;color:var(--ink)">{{ formatDate(referral.acknowledged_at) }}</div>
          </div>
        </div>
      </div>

      <!-- Your own copy of the Admission Slip, once GCU has issued one. -->
      <div v-if="isClassAttendance && referral.admission_issued_at" class="icard" style="margin-bottom:20px">
        <div class="icard-header"><span class="icard-title">Admission Slip</span></div>
        <div class="icard-body">
          <AdmissionSlipPaper
            readonly
            :model-value="issuedAdmissionSlip"
            :student="referral.student"
            :personnel="referral.admission_issued_by?.name || ''"
            :issued-at="referral.admission_issued_at"
            :show-doc="false"
          />
        </div>
      </div>

      <!-- Your own copy of every Feedback Slip GCU has sent for this referral. -->
      <div v-if="referral.feedback_slips?.length" class="icard" style="margin-bottom:20px">
        <div class="icard-header"><span class="icard-title">Feedback Slip</span></div>
        <div class="icard-body" style="display:flex;flex-direction:column;gap:14px">
          <FeedbackSlipPaper
            v-for="slip in referral.feedback_slips"
            :key="slip.id"
            :slip="slip"
            :student="referral.student"
            :show-doc="false"
          />
        </div>
      </div>
    </template>
  </div>
</template>

<script setup>
import { ref, computed, onMounted, onBeforeUnmount } from 'vue';
import { useRoute } from 'vue-router';
import axios from 'axios';
import { usePageSubtitleStore } from '../../stores/pageSubtitle';
import AdmissionSlipPaper from '../../components/AdmissionSlipPaper.vue';
import FeedbackSlipPaper from '../../components/FeedbackSlipPaper.vue';

const route = useRoute();
const pageSubtitle = usePageSubtitleStore();
const API_BASE = `${import.meta.env.VITE_API_URL || ''}/api`;

const loading = ref(true);
const referral = ref({});

const isClassAttendance = computed(() => referral.value.referral_type === 'class_attendance');

// The slip as the paper form has it (see components/AdmissionSlipPaper.vue) -
// same mapping ReferralDetails (staff side) uses to show an issued slip.
const issuedAdmissionSlip = computed(() => {
  const r = referral.value;
  const d = r.admission_details || {};
  return {
    admission_date:     r.admission_date ? String(r.admission_date).slice(0, 10) : '',
    admission_time_in:  r.admission_time_in ? String(r.admission_time_in).slice(0, 5) : '',
    admission_time_out: r.admission_time_out ? String(r.admission_time_out).slice(0, 5) : '',
    excused:            r.admission_excused === true ? '1' : (r.admission_excused === false ? '0' : ''),
    remarks:            r.admission_remarks || '',
    days_count:         d.days_count || '',
    causes:             Array.isArray(d.causes) ? [...d.causes] : [],
    cause_activity:     d.cause_activity || '',
    cause_others:       d.cause_others || '',
    actions:            Array.isArray(d.actions) ? [...d.actions] : [],
    action_others:      d.action_others || '',
  };
});

function authHeaders() {
  return { headers: { Authorization: `Bearer ${localStorage.getItem('student_token')}` } };
}

function toTitleCase(str) {
  if (!str) return '';
  return str.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase()).replace(/\b(Sdu|Gcu|Tmdu|Oss|Sif|Par)\b/g, m => m.toUpperCase());
}

function formatDate(date) {
  return date ? new Date(date).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' }) : '-';
}

onMounted(async () => {
  try {
    const res = await axios.get(`${API_BASE}/student/referrals/${route.params.id}`, authHeaders());
    referral.value = res.data;
    // Bug (10/25/2026): same breadcrumb gap as Appointment Details - this
    // page's real title (its referral code) only exists once the record
    // has loaded, so it's handed to the layout through the shared store.
    pageSubtitle.set(referral.value.referral_code);
  } catch (e) {
    console.error(e);
  } finally {
    loading.value = false;
  }
});

onBeforeUnmount(() => pageSubtitle.clear());
</script>